def parse_port(raw):
    """Parse a port string; None or whitespace-only returns 3000."""
    if raw is None:
        return 3000
    text = raw.strip()
    if not text:
        return 3000
    if not all("0" <= ch <= "9" for ch in text):
        raise ValueError(f"Invalid port: {raw!r}")
    port = int(text)
    if port < 1 or port > 65535:
        raise ValueError(f"Port out of range 1-65535: {raw!r}")
    return port

