def parse_port(raw):
    """Parse a port string. None or blank returns 3000; otherwise require ASCII digits in 1..65535."""
    if raw is None:
        return 3000
    value = raw.strip()
    if value == "":
        return 3000
    if not (value.isascii() and value.isdigit()):
        raise ValueError(f"invalid port: {raw!r}")
    port = int(value)
    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range 1-65535: {port}")
    return port

